/* Desktop printing helper.
   Electron does not provide Chromium's browser print-preview page, so the
   installed app asks the main process to open the native Windows print dialog. */
async function printCurrentView(){
  // Give the DOM two paint frames to finish switching views/rendering all SF9s.
  await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  if(window.eclassAPI && typeof window.eclassAPI.printCurrent === "function"){
    try{
      const result = await window.eclassAPI.printCurrent();
      if(result && result.ok === false && result.error && !/cancel/i.test(result.error)){
        alert("Unable to start printing: " + result.error);
      }
      return;
    }catch(err){
      alert("Unable to start printing: " + (err && err.message ? err.message : err));
      return;
    }
  }
  // Browser-only fallback when the HTML file is opened outside Electron.
  window.print();
}

