const BANDS = {
  Advancing:     {min:90, full:"Consistently demonstrates skills and understanding that meet or exceed standards with independence, flexibility, and depth."},
  Benchmarking:  {min:79, full:"Demonstrates expected grade-level skills and understanding competently and independently."},
  Connecting:    {min:75, full:"Demonstrates sufficient understanding and application of grade-level standards with occasional guidance and support."},
  Developing:    {min:65, full:"Demonstrates partial understanding and inconsistent application of skills, requires targeted support and scaffolding."},
  Emerging:      {min:0,  full:"Does not yet demonstrate foundational skills and understanding; requires intensive support."}
};
function bandFor(grade){
  if(grade>=90) return "Advancing";
  if(grade>=79) return "Benchmarking";
  if(grade>=75) return "Connecting";
  if(grade>=65) return "Developing";
  return "Emerging";
}
function transmute(initialGrade){
  if(initialGrade===null || initialGrade===undefined || isNaN(initialGrade)) return null;
  let ig = Math.max(0, Math.min(100, initialGrade));
  for(const row of TRANSMUTE_TABLE){
    if(ig >= row.ig_min && ig <= row.ig_max){
      const band = bandFor(row.grade);
      return {grade:row.grade, band, full: BANDS[band].full};
    }
  }
  const band = bandFor(ig);
  return {grade: Math.round(ig), band, full: BANDS[band].full};
}

