function ensureStudentExtras(cls, sid){
  if(!cls.otherGrades) cls.otherGrades = {};
  if(!cls.attendance) cls.attendance = {};
  if(!cls.comments) cls.comments = {};
  if(!cls.otherGrades[sid]) cls.otherGrades[sid] = {};
  STANDARD_AREAS.forEach(a=>{
    if(!cls.otherGrades[sid][a.key]) cls.otherGrades[sid][a.key] = {term1:"",term2:"",term3:""};
  });
  if(!cls.attendance[sid]) cls.attendance[sid] = {};
  ATT_MONTHS.forEach(m=>{ if(!cls.attendance[sid][m]) cls.attendance[sid][m] = {classDays:"", present:""}; });
  if(!cls.comments[sid]) cls.comments[sid] = {term1:"",term2:"",term3:""};
  if(!cls.meta.schoolAddress && cls.meta.schoolAddress !== "") cls.meta.schoolAddress = cls.meta.schoolAddress || "";
}

function validStateCandidate(parsed){
  return !!(parsed && typeof parsed === "object" && parsed.classes && typeof parsed.classes === "object" && Object.keys(parsed.classes).length);
}
function persistenceRevision(state){
  const n=Number(state && state._persistence && state._persistence.revision);
  return Number.isFinite(n) && n>=0 ? n : 0;
}
function persistenceTime(state){
  const t=Date.parse(state && state._persistence && state._persistence.modifiedAt || "");
  return Number.isFinite(t) ? t : 0;
}
function loadState(){
  const candidates=[];
  try{
    if(window.eclassAPI && window.eclassAPI.loadDataSync){
      const desktopRaw=window.eclassAPI.loadDataSync();
      if(desktopRaw){
        const parsed=JSON.parse(desktopRaw);
        if(validStateCandidate(parsed)) candidates.push({source:"desktop",data:validateBackupForImport(parsed)});
      }
    }
  }catch(e){ console.warn("Could not load desktop data",e); }
  try{
    const raw=localStorage.getItem(STORE_KEY)||localStorage.getItem(LEGACY_STORE_KEY);
    if(raw){
      const parsed=JSON.parse(raw);
      if(validStateCandidate(parsed)) candidates.push({source:"local",data:validateBackupForImport(parsed)});
    }
  }catch(e){ console.warn("Could not load local recovery data",e); }
  if(candidates.length){
    candidates.sort((a,b)=>{
      const rev=persistenceRevision(b.data)-persistenceRevision(a.data);
      if(rev) return rev;
      const tm=persistenceTime(b.data)-persistenceTime(a.data);
      if(tm) return tm;
      return a.source==="desktop" ? -1 : 1;
    });
    return candidates[0].data;
  }
  const c=newClass("Grade 10 Science — Section 1");
  return {classes:{[c.id]:c},activeId:c.id,_persistence:{revision:0,modifiedAt:new Date().toISOString()}};
}

let SAVE_QUEUE=Promise.resolve();
function setSaveStatus(text,isError=false){
  const el=document.getElementById("statusRight");
  if(!el) return;
  el.textContent=text;
  el.style.color=isError?"var(--red-pen)":"";
  el.style.fontWeight=isError?"800":"";
}
function saveState(){
  if(!APP._persistence || typeof APP._persistence!=="object") APP._persistence={};
  APP._persistence.revision=persistenceRevision(APP)+1;
  APP._persistence.modifiedAt=new Date().toISOString();
  const revision=APP._persistence.revision;
  const serialized=JSON.stringify(APP);

  try{ localStorage.setItem(STORE_KEY,serialized); }
  catch(err){ console.warn("Local recovery save failed",err); }

  if(!(window.eclassAPI && typeof window.eclassAPI.saveData==="function")){
    setSaveStatus("Saved locally " + new Date().toLocaleTimeString());
    return Promise.resolve({ok:true,localOnly:true});
  }

  setSaveStatus("Saving…");
  SAVE_QUEUE=SAVE_QUEUE.catch(()=>null).then(async()=>{
    let result;
    try{ result=await window.eclassAPI.saveData(serialized); }
    catch(err){ result={ok:false,error:err && err.message ? err.message : String(err)}; }
    if(persistenceRevision(APP)===revision){
      if(result && result.ok) setSaveStatus("Saved " + new Date().toLocaleTimeString());
      else setSaveStatus("⚠ NOT SAVED TO DISK — retry or export a backup",true);
    }
    if(!result || !result.ok) console.warn("Desktop save failed",result && result.error ? result.error : result);
    return result;
  });
  return SAVE_QUEUE;
}

