function resizeSchoolLogo(file){
  return new Promise((resolve, reject)=>{
    if(!file){ reject(new Error("No image selected.")); return; }
    if(!/^image\/(png|jpeg|webp)$/i.test(file.type || "")){
      reject(new Error("Please select a PNG, JPG/JPEG, or WebP image.")); return;
    }
    if(file.size > 10 * 1024 * 1024){
      reject(new Error("The logo image is too large. Please use an image smaller than 10 MB.")); return;
    }
    const reader = new FileReader();
    reader.onerror = ()=>reject(new Error("The selected image could not be read."));
    reader.onload = ()=>{
      const img = new Image();
      img.onerror = ()=>reject(new Error("The selected file is not a readable image."));
      img.onload = ()=>{
        const maxSide = 700;
        const scale = Math.min(1, maxSide / Math.max(img.naturalWidth || 1, img.naturalHeight || 1));
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
        canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
        const ctx = canvas.getContext("2d");
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/png"));
      };
      img.src = String(reader.result || "");
    };
    reader.readAsDataURL(file);
  });
}

