/* =========================================================================
   GRADE COMPUTATION
   ========================================================================= */
function categoryPS(cat, scoreMap){
  const comps=cat.components.filter(c=>Number(c.hps)>0);
  if(!comps.length) return null;
  const anyEntered=comps.some(c=>scoreMap && scoreMap[c.id]!==undefined && scoreMap[c.id]!=="" && scoreMap[c.id]!==null);
  if(!anyEntered) return null;
  if(cat.mode==="custom"){
    let ps=0;
    comps.forEach(c=>{
      const raw=(scoreMap && scoreMap[c.id]!==undefined && scoreMap[c.id]!=="")?Number(scoreMap[c.id]):0;
      const contribution=Math.round((raw/Number(c.hps))*Number(c.subWeight||0)*100)/100;
      ps+=contribution;
    });
    return Math.round(ps*100)/100;
  }
  const sumHps=comps.reduce((sum,c)=>sum+Number(c.hps),0);
  const rawTotal=comps.reduce((sum,c)=>{
    const raw=(scoreMap && scoreMap[c.id]!==undefined && scoreMap[c.id]!=="")?Number(scoreMap[c.id]):0;
    return sum+(Number.isFinite(raw)?raw:0);
  },0);
  return sumHps>0 ? Math.round((rawTotal/sumHps*100)*100)/100 : null;
}
function studentTermResult(cls, term, studentId){
  const scoreMap = (cls.scores[term] && cls.scores[term][studentId]) || {};
  const catKeys = ["WW","PT","EXAM"];
  const parts = {};
  let anyCat = false;
  let initial = 0;
  catKeys.forEach(k=>{
    const cat = cls.categories[k];
    const ps = categoryPS(cat, scoreMap[k]);
    const ws = ps===null ? null : Math.round(ps*cat.weight*100)/100;
    parts[k] = {ps, ws};
    if(ps!==null){ anyCat = true; initial += ws; }
  });
  if(!anyCat) return {parts, initial:null, term:null, band:null};
  initial = Math.round(initial*100)/100;
  const t = transmute(initial);
  return {parts, initial, term: t ? t.grade : null, band: t ? t.band : null};
}
/* Whole-number averaging: whenever several already-graded values are
   combined (MAPEH from Music+PE, General Average from all subjects, Final
   Grade from term grades), the result rounds to the nearest whole number,
   and that rounded whole number — not the raw decimal — is what feeds into
   any further averaging. */
function averageWhole(vals){
  const present = vals.filter(v=>v!==null && v!==undefined && !isNaN(v));
  if(!present.length) return null;
  return Math.round(present.reduce((a,b)=>a+b,0)/present.length);
}

function studentFinalResult(cls, studentId){
  const terms = ["term1","term2","term3"].map(t=>studentTermResult(cls,t,studentId).term).filter(v=>v!==null && v!==undefined);
  if(!terms.length) return {final:null, band:null, count:0};
  const final = averageWhole(terms);
  const t = transmute(final);
  return {final, band: t?t.band:null, count: terms.length};
}

/* =========================================================================
   RENDER: shell
   ========================================================================= */
function render(){
  renderClassPicker();
  document.querySelectorAll("nav.tabs .tab").forEach(b=>{
    b.classList.toggle("active", b.dataset.tab === activeTab);
  });
  const main = document.getElementById("main");
  main.innerHTML = "";
  const cls = activeClass();
  if(!cls){ main.innerHTML = `<div class="empty-state"><h2>No class yet</h2><p>Create one with "+ New Class" above.</p></div>`; return; }
  if(activeTab==="setup") renderSetup(main, cls);
  else if(activeTab==="roster") renderRoster(main, cls);
  else if(activeTab==="term1") renderTerm(main, cls, "term1", "Term 1");
  else if(activeTab==="term2") renderTerm(main, cls, "term2", "Term 2");
  else if(activeTab==="term3") renderTerm(main, cls, "term3", "Term 3");
  else if(activeTab==="final") renderFinal(main, cls);
  else if(activeTab==="summary") renderSummary(main, cls);
  else if(activeTab==="report") renderReport(main, cls);
}

function renderClassPicker(){
  const sel = document.getElementById("classSelect");
  sel.innerHTML = "";
  Object.values(APP.classes).sort((a,b)=>a.createdAt-b.createdAt).forEach(c=>{
    const opt = document.createElement("option");
    opt.value = c.id;
    opt.textContent = c.meta.className || "(untitled class)";
    if(c.id === APP.activeId) opt.selected = true;
    sel.appendChild(opt);
  });
}

