/* ===== v1.0.4: Import raw Class Record scores from CSV =====================
   The importer is intentionally mapping-based. It auto-detects familiar
   headers (Name/LRN/WW1/PT1/ST1/TE etc.) but lets the teacher correct the
   mapping before any data is changed. This keeps it usable with CSV files
   exported from different offline Excel class-record formats. */
function csvHeaderKey(value){
  return String(value==null?"":value)
    .replace(/^\uFEFF/,"")
    .trim().toLowerCase()
    .replace(/&/g,"and")
    .replace(/[^a-z0-9]+/g,"");
}
function csvColumnLabel(header, i){
  let n=i+1, letters="";
  while(n){ n--; letters=String.fromCharCode(65+(n%26))+letters; n=Math.floor(n/26); }
  const h=String(header==null?"":header).trim();
  return `${letters}: ${h || "(blank header)"}`;
}
function detectCsvHeaderRow(rows, cls){
  const candidates = rows.slice(0, Math.min(12, rows.length));
  const scoreNames=[];
  ["WW","PT","EXAM"].forEach(k=>cls.categories[k].components.forEach(c=>scoreNames.push(csvHeaderKey(c.name))));
  let best={index:0,score:-1};
  candidates.forEach((row,idx)=>{
    const keys=row.map(csvHeaderKey);
    let score=0;
    if(keys.some(k=>["name","learnername","learnersname","studentname","studentsname","fullname"].includes(k))) score+=8;
    if(keys.some(k=>k==="lrn" || k==="learnerreferencenumber")) score+=3;
    scoreNames.forEach(k=>{ if(k && keys.includes(k)) score+=2; });
    if(score>best.score) best={index:idx,score};
  });
  return best.index;
}
function findHeaderIndex(headers, aliases){
  const keys=headers.map(csvHeaderKey);
  const wanted=aliases.map(csvHeaderKey);
  for(const w of wanted){ const i=keys.indexOf(w); if(i>=0) return i; }
  return -1;
}
function componentHeaderAliases(catKey, comp, index){
  const aliases=[comp.name, `${catKey}${index+1}`];
  const n=(String(comp.name).match(/(\d+)/)||[])[1] || String(index+1);
  if(catKey==="WW") aliases.push(`WW ${n}`,`Written Work ${n}`,`Written Works ${n}`,`Written/Oral Work ${n}`);
  if(catKey==="PT") aliases.push(`PT ${n}`,`Performance Task ${n}`,`Product/Performance Task ${n}`);
  if(catKey==="EXAM"){
    aliases.push(`Exam ${n}`,`Examination ${n}`);
    const ck=csvHeaderKey(comp.name);
    if(ck==="te") aliases.push("Term Exam","Quarterly Exam","Term Examination","TE");
    if(ck.startsWith("st")) aliases.push(`Summative Test ${n}`,`ST ${n}`);
  }
  return [...new Set(aliases)];
}
function normalizeLearnerName(name){
  return String(name||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"")
    .replace(/[^a-z0-9]+/g," ").trim().replace(/\s+/g," ");
}
function learnerTokenKey(name){
  return normalizeLearnerName(name).split(" ").filter(Boolean).sort().join("|");
}
function buildStudentImportIndexes(cls){
  const byLrn=new Map(), byName=new Map(), byTokens=new Map();
  cls.students.forEach(s=>{
    const l=String(s.lrn||"").replace(/\D/g,""); if(l) byLrn.set(l,s);
    const n=normalizeLearnerName(s.name); if(n) byName.set(n,s);
    const t=learnerTokenKey(s.name); if(t){
      if(!byTokens.has(t)) byTokens.set(t,[]);
      byTokens.get(t).push(s);
    }
  });
  return {byLrn,byName,byTokens};
}
function importNumericScore(raw){
  const s=String(raw==null?"":raw).trim();
  if(!s) return null;
  // Accept plain numbers and Excel-exported values such as "20.5".
  const n=Number(s.replace(/,/g,""));
  return Number.isFinite(n) ? n : NaN;
}
function showScoreImportDialog(cls, termKey, rows, fileName){
  return new Promise(resolve=>{
    if(!rows.length){ resolve(null); return; }
    const headerRow=detectCsvHeaderRow(rows,cls);
    const headers=rows[headerRow].map(x=>String(x||"").trim());
    const dataRows=rows.slice(headerRow+1).filter(r=>r.some(v=>String(v||"").trim()!==""));
    if(!headers.length || !dataRows.length){ resolve({error:"No usable header/data rows were found in the CSV."}); return; }

    const autoName=findHeaderIndex(headers,["Name","Learner Name","Learner's Name","Student Name","Full Name"]);
    const autoLrn=findHeaderIndex(headers,["LRN","Learner Reference Number"]);
    const autoSex=findHeaderIndex(headers,["Sex","Gender"]);
    const mappings=[];
    ["WW","PT","EXAM"].forEach(catKey=>{
      cls.categories[catKey].components.forEach((comp,index)=>{
        const col=findHeaderIndex(headers,componentHeaderAliases(catKey,comp,index));
        mappings.push({catKey,comp,index,col});
      });
    });

    const backdrop=document.createElement("div"); backdrop.className="app-modal-backdrop no-print";
    const modal=document.createElement("div"); modal.className="app-modal import-modal"; modal.setAttribute("role","dialog"); modal.setAttribute("aria-modal","true");
    const optionHtml=(selected,allowNone=true)=>`${allowNone?'<option value="-1">— Not mapped —</option>':''}${headers.map((h,i)=>`<option value="${i}" ${i===selected?"selected":""}>${esc(csvColumnLabel(h,i))}</option>`).join("")}`;
    const autoCount=mappings.filter(m=>m.col>=0).length;
    modal.innerHTML=`
      <h3>Import Scores CSV — ${esc(TERM_LABELS[termKey])}</h3>
      <p><strong>${esc(fileName||"CSV file")}</strong> was read successfully. Confirm the column mapping below before importing. Nothing is changed until you click <strong>Import Scores</strong>.</p>
      <div class="import-summary">Detected header row: <strong>${headerRow+1}</strong> &nbsp;•&nbsp; Data rows: <strong>${dataRows.length}</strong> &nbsp;•&nbsp; Score columns auto-mapped: <strong>${autoCount}/${mappings.length}</strong></div>
      <div class="import-grid">
        <div class="field"><label>Learner Name *</label><select id="impName">${optionHtml(autoName,true)}</select></div>
        <div class="field"><label>LRN (optional)</label><select id="impLrn">${optionHtml(autoLrn,true)}</select></div>
        <div class="field"><label>Sex/Gender (for new learners)</label><select id="impSex">${optionHtml(autoSex,true)}</select></div>
      </div>
      <div class="hint">The app matches existing learners by LRN first, then by name. Score values are imported as <strong>raw scores</strong>; the app will compute PS, WS, Initial Grade and Term Grade normally. Ensure the HPS/component setup in this app matches the Excel file.</div>
      <div class="scroll-x" style="margin-top:10px;">
        <table class="import-map-table">
          <thead><tr><th>Component</th><th>HPS in App</th><th>CSV Column</th></tr></thead>
          <tbody>${mappings.map((m,i)=>`<tr><td><strong>${esc(m.catKey)}</strong> — ${esc(m.comp.name)}</td><td>${esc(m.comp.hps)}</td><td><select class="imp-score-map" data-map-index="${i}">${optionHtml(m.col,true)}</select></td></tr>`).join("")}</tbody>
        </table>
      </div>
      <div class="import-options">
        <label><input type="checkbox" id="impAddLearners"> Add learners that are not yet in the roster</label>
        <label><input type="checkbox" id="impOverwrite"> Overwrite existing raw scores</label>
      </div>
      <div class="hint">Safety default: existing scores are preserved. Turn on “Overwrite existing raw scores” only when the CSV should replace them.</div>
      <div class="app-modal-error" id="impError"></div>
      <div class="app-modal-actions"><button type="button" class="cancel" id="impCancel">Cancel</button><button type="button" class="primary" id="impConfirm">Import Scores</button></div>`;
    backdrop.appendChild(modal); document.body.appendChild(backdrop);

    const finish=result=>{ document.removeEventListener("keydown",onKey,true); backdrop.remove(); resolve(result); };
    const onKey=e=>{ if(e.key==="Escape"){ e.preventDefault(); finish(null); } };
    document.addEventListener("keydown",onKey,true);
    modal.querySelector("#impCancel").addEventListener("click",()=>finish(null));
    backdrop.addEventListener("click",e=>{ if(e.target===backdrop) finish(null); });
    modal.querySelector("#impConfirm").addEventListener("click",()=>{
      const nameCol=Number(modal.querySelector("#impName").value);
      if(nameCol<0){ modal.querySelector("#impError").textContent="Please select the learner-name column."; return; }
      const scoreMappings=mappings.map((m,i)=>({...m,col:Number(modal.querySelector(`.imp-score-map[data-map-index="${i}"]`).value)})).filter(m=>m.col>=0);
      if(!scoreMappings.length){ modal.querySelector("#impError").textContent="Map at least one score component to a CSV column."; return; }
      finish({
        headerRow,dataRows,headers,nameCol,
        lrnCol:Number(modal.querySelector("#impLrn").value),
        sexCol:Number(modal.querySelector("#impSex").value),
        scoreMappings,
        addLearners:modal.querySelector("#impAddLearners").checked,
        overwrite:modal.querySelector("#impOverwrite").checked
      });
    });
  });
}
function applyScoreCsvImport(cls, termKey, config){
  const idx=buildStudentImportIndexes(cls);
  let matched=0, added=0, imported=0, preserved=0, invalid=0, unmatched=0;
  const seenStudents=new Set();
  for(const row of config.dataRows){
    const name=String(row[config.nameCol]||"").trim(); if(!name) continue;
    const lrn=config.lrnCol>=0 ? String(row[config.lrnCol]||"").replace(/\D/g,"") : "";
    let student=null;
    if(lrn && idx.byLrn.has(lrn)) student=idx.byLrn.get(lrn);
    if(!student){ const nk=normalizeLearnerName(name); if(nk && idx.byName.has(nk)) student=idx.byName.get(nk); }
    if(!student){ const tk=learnerTokenKey(name), list=tk?idx.byTokens.get(tk):null; if(list && list.length===1) student=list[0]; }
    if(!student && config.addLearners){
      if(cls.students.length>=1000) throw new Error("Score import would exceed the 1,000-learner safety limit for one class.");
      let sex="M";
      if(config.sexCol>=0){ const sr=String(row[config.sexCol]||"").trim().toLowerCase(); if(sr.startsWith("f")) sex="F"; else if(sr.startsWith("m")) sex="M"; }
      student={id:uid("s"),name,lrn,age:"",sex}; cls.students.push(student); added++;
      if(lrn) idx.byLrn.set(lrn,student);
      idx.byName.set(normalizeLearnerName(name),student);
      const tk=learnerTokenKey(name); if(tk){ if(!idx.byTokens.has(tk)) idx.byTokens.set(tk,[]); idx.byTokens.get(tk).push(student); }
    }
    if(!student){ unmatched++; continue; }
    if(!seenStudents.has(student.id)){ matched++; seenStudents.add(student.id); }
    const sm=cls.scores[termKey][student.id] || (cls.scores[termKey][student.id]={WW:{},PT:{},EXAM:{}});
    for(const map of config.scoreMappings){
      const raw=row[map.col]; const n=importNumericScore(raw); if(n===null) continue;
      const hps=Number(map.comp.hps);
      if(Number.isNaN(n) || n<0 || (Number.isFinite(hps) && hps>0 && n>hps)){ invalid++; continue; }
      if(!sm[map.catKey]) sm[map.catKey]={};
      const old=sm[map.catKey][map.comp.id];
      if(!config.overwrite && old!==undefined && old!==null && old!==""){ preserved++; continue; }
      sm[map.catKey][map.comp.id]=n; imported++;
    }
  }
  return {matched,added,imported,preserved,invalid,unmatched};
}
function showInfoDialog(title, message){
  return new Promise(resolve=>{
    const backdrop=document.createElement("div"); backdrop.className="app-modal-backdrop no-print";
    const modal=document.createElement("div"); modal.className="app-modal"; modal.setAttribute("role","dialog"); modal.setAttribute("aria-modal","true");
    modal.innerHTML=`<h3>${esc(title||"Information")}</h3><p>${esc(message||"")}</p><div class="app-modal-actions"><button type="button" class="primary">Close</button></div>`;
    backdrop.appendChild(modal); document.body.appendChild(backdrop);
    const close=()=>{ document.removeEventListener("keydown",onKey,true); backdrop.remove(); resolve(); };
    const onKey=e=>{ if(e.key==="Escape" || e.key==="Enter"){ e.preventDefault(); close(); } };
    document.addEventListener("keydown",onKey,true);
    modal.querySelector("button").addEventListener("click",close);
    backdrop.addEventListener("click",e=>{ if(e.target===backdrop) close(); });
  });
}
function showImportResult(stats, termKey){
  const parts=[
    `${stats.imported} raw score${stats.imported===1?"":"s"} imported`,
    `${stats.matched} learner${stats.matched===1?"":"s"} matched`
  ];
  if(stats.added) parts.push(`${stats.added} learner${stats.added===1?"":"s"} added to roster`);
  if(stats.preserved) parts.push(`${stats.preserved} existing score${stats.preserved===1?"":"s"} preserved`);
  if(stats.unmatched) parts.push(`${stats.unmatched} CSV row${stats.unmatched===1?"":"s"} not matched`);
  if(stats.invalid) parts.push(`${stats.invalid} invalid/out-of-HPS value${stats.invalid===1?"":"s"} skipped`);
  return showInfoDialog(`CSV Import Complete — ${TERM_LABELS[termKey]}`,parts.join(" • "));
}


/* ===== v1.0.7: Import a filled Official ECR .xlsx =========================
   The source workbook uses the same fixed official template as our export.
   No column mapping is required: names, sex blocks, HPS and raw-score cells
   are read by the desktop process, then the app recalculates grades itself. */
function officialImportTermKey(termNo){
  return Number(termNo)===2 ? "term2" : Number(termNo)===3 ? "term3" : "term1";
}

function showOfficialEcrImportDialog(data,fileName,currentTermKey){
  return new Promise(resolve=>{
    const targetTermKey=officialImportTermKey(data.termNo);
    const male=(data.students||[]).filter(s=>s.sex==="M").length;
    const female=(data.students||[]).filter(s=>s.sex==="F").length;
    const hps=d=>Array.isArray(d)?d.map(v=>v===""?"—":String(v)).join(", "):"";
    const backdrop=document.createElement("div"); backdrop.className="app-modal-backdrop no-print";
    const modal=document.createElement("div"); modal.className="app-modal import-modal"; modal.setAttribute("role","dialog"); modal.setAttribute("aria-modal","true");
    const differentTerm=targetTermKey!==currentTermKey;
    const warnings=(data.warnings||[]).slice(0,4);
    modal.innerHTML=`
      <h3>Import Filled Official ECR</h3>
      <p><strong>${esc(fileName||"Official ECR workbook")}</strong> matches the official Class Record layout. Review the detected data before importing.</p>
      <div class="import-summary">
        <strong>Detected:</strong> ${esc(TERM_LABELS[targetTermKey])}
        &nbsp;•&nbsp; <strong>Learners:</strong> ${data.students.length} (${male} male, ${female} female)
        &nbsp;•&nbsp; <strong>Subject:</strong> ${esc((data.meta&&data.meta.subject)||"—")}
        &nbsp;•&nbsp; <strong>Grade/Section:</strong> ${esc((data.meta&&data.meta.gradeLevel)||"—")} / ${esc((data.meta&&data.meta.section)||"—")}
      </div>
      ${differentTerm?`<div class="import-summary" style="border-color:var(--red-pen);"><strong>Term notice:</strong> You opened ${esc(TERM_LABELS[currentTermKey])}, but the workbook identifies itself as <strong>${esc(TERM_LABELS[targetTermKey])}</strong>. It will be imported into the detected term automatically.</div>`:""}
      <div class="scroll-x" style="margin-top:10px;">
        <table class="import-map-table">
          <thead><tr><th>Component</th><th>Detected HPS</th><th>Weight</th></tr></thead>
          <tbody>
            <tr><td><strong>Written / Oral Works</strong> (WW1–WW5)</td><td>${esc(hps(data.categories.WW.hps))}</td><td>${Math.round(Number(data.categories.WW.weight||0)*10000)/100}%</td></tr>
            <tr><td><strong>Performance Tasks</strong> (PT1–PT3)</td><td>${esc(hps(data.categories.PT.hps))}</td><td>${Math.round(Number(data.categories.PT.weight||0)*10000)/100}%</td></tr>
            <tr><td><strong>Examinations</strong> (ST1, ST2, TE)</td><td>${esc(hps(data.categories.EXAM.hps))}</td><td>${Math.round(Number(data.categories.EXAM.weight||0)*10000)/100}%</td></tr>
          </tbody>
        </table>
      </div>
      <p style="margin-top:12px;">The app will update the class information available in the workbook, match existing learners by name, add missing learners, copy the HPS/weights, and <strong>replace the raw scores for the detected term</strong>. Other terms are not changed.</p>
      <div class="hint">PS, WS, Initial Grade, Term Grade and Descriptor are not blindly copied from Excel. They are recalculated using this app's grading logic from the imported raw scores. LRN and age remain unchanged because they are not fields in this official ECR template.</div>
      ${warnings.length?`<div class="app-modal-error" style="margin-top:10px;">${warnings.map(w=>esc(w)).join("<br>")}</div>`:""}
      <div class="app-modal-actions"><button type="button" class="cancel" id="offImpCancel">Cancel</button><button type="button" class="primary" id="offImpConfirm">Import Official ECR</button></div>`;
    backdrop.appendChild(modal); document.body.appendChild(backdrop);
    const finish=result=>{ document.removeEventListener("keydown",onKey,true); backdrop.remove(); resolve(result); };
    const onKey=e=>{ if(e.key==="Escape"){ e.preventDefault(); finish(false); } };
    document.addEventListener("keydown",onKey,true);
    modal.querySelector("#offImpCancel").addEventListener("click",()=>finish(false));
    modal.querySelector("#offImpConfirm").addEventListener("click",()=>finish(true));
    backdrop.addEventListener("click",e=>{ if(e.target===backdrop) finish(false); });
  });
}

function applyOfficialEcrImport(cls,data){
  const targetTermKey=officialImportTermKey(data.termNo);
  const ww=cls.categories&&cls.categories.WW, pt=cls.categories&&cls.categories.PT, ex=cls.categories&&cls.categories.EXAM;
  if(!ww||!pt||!ex||ww.components.length!==5||pt.components.length!==3||ex.components.length!==3){
    throw new Error("This official ECR importer requires the class setup to contain exactly 5 WW, 3 PT and 3 Examination components.");
  }

  // Import the metadata that actually exists on the official Class Record.
  const m=data.meta||{};
  ["region","division","schoolId","schoolName","schoolYear","gradeLevel","teacher","subject","section"].forEach(k=>{
    if(m[k]!==undefined && m[k]!==null && String(m[k]).trim()!=="") cls.meta[k]=String(m[k]).trim();
  });

  // The official form is authoritative for HPS and component weighting.
  const applyHps=(cat,vals)=>cat.components.forEach((c,i)=>{
    const n=Number(vals&&vals[i]); if(Number.isFinite(n)&&n>=0) c.hps=n;
  });
  applyHps(ww,data.categories&&data.categories.WW&&data.categories.WW.hps);
  applyHps(pt,data.categories&&data.categories.PT&&data.categories.PT.hps);
  applyHps(ex,data.categories&&data.categories.EXAM&&data.categories.EXAM.hps);
  const setWeight=(cat,v)=>{ const n=Number(v); if(Number.isFinite(n)&&n>=0) cat.weight=n; };
  setWeight(ww,data.categories&&data.categories.WW&&data.categories.WW.weight);
  setWeight(pt,data.categories&&data.categories.PT&&data.categories.PT.weight);
  setWeight(ex,data.categories&&data.categories.EXAM&&data.categories.EXAM.weight);
  const sw=data.categories&&data.categories.EXAM&&data.categories.EXAM.subWeights;
  ex.components.forEach((c,i)=>{ const n=Number(sw&&sw[i]); if(Number.isFinite(n)&&n>=0) c.subWeight=n; });

  if(!cls.scores[targetTermKey]) cls.scores[targetTermKey]={};
  const idx=buildStudentImportIndexes(cls);
  let matched=0,added=0,importedScores=0,invalid=0,gradeChecks=0,gradeMismatches=0;
  const importedStudentIds=[];

  for(const source of (data.students||[])){
    const name=String(source.name||"").trim(); if(!name) continue;
    let student=null;
    const nk=normalizeLearnerName(name);
    if(nk&&idx.byName.has(nk)) student=idx.byName.get(nk);
    if(!student){
      const tk=learnerTokenKey(name), list=tk?idx.byTokens.get(tk):null;
      if(list&&list.length===1) student=list[0];
    }
    if(!student){
      student={id:uid("s"),name,lrn:"",age:"",sex:source.sex==="F"?"F":"M"};
      cls.students.push(student); ensureStudentExtras(cls,student.id); added++;
      idx.byName.set(normalizeLearnerName(name),student);
      const tk=learnerTokenKey(name); if(tk){ if(!idx.byTokens.has(tk)) idx.byTokens.set(tk,[]); idx.byTokens.get(tk).push(student); }
    }else{
      matched++;
      student.name=name;
      student.sex=source.sex==="F"?"F":"M";
      ensureStudentExtras(cls,student.id);
    }

    // Replace this learner's raw scores in the imported term. Blank official
    // cells intentionally clear old values in the same term.
    const sm={WW:{},PT:{},EXAM:{}};
    const importCat=(catKey,cat,values)=>{
      (values||[]).forEach((raw,i)=>{
        if(i>=cat.components.length||raw===""||raw===null||raw===undefined) return;
        const n=Number(raw), h=Number(cat.components[i].hps||0);
        if(!Number.isFinite(n)||n<0||(h>0&&n>h)){ invalid++; return; }
        sm[catKey][cat.components[i].id]=n; importedScores++;
      });
    };
    importCat("WW",ww,source.scores&&source.scores.WW);
    importCat("PT",pt,source.scores&&source.scores.PT);
    importCat("EXAM",ex,source.scores&&source.scores.EXAM);
    cls.scores[targetTermKey][student.id]=sm;
    importedStudentIds.push({student,source});
  }

  // When the workbook has a cached official term grade, compare it against
  // the app's recomputation as a verification signal only; never overwrite.
  importedStudentIds.forEach(({student,source})=>{
    const official=Number(source.officialTermGrade);
    if(!Number.isFinite(official)) return;
    const computed=studentTermResult(cls,targetTermKey,student.id).term;
    if(computed===null||computed===undefined) return;
    gradeChecks++;
    if(Number(computed)!==official) gradeMismatches++;
  });

  return {termKey:targetTermKey,matched,added,learners:importedStudentIds.length,importedScores,invalid,gradeChecks,gradeMismatches,warnings:(data.warnings||[]).length};
}

async function importOfficialEcrIntoClass(cls,currentTermKey){
  if(!window.eclassAPI||typeof window.eclassAPI.importOfficialEcr!=="function"){
    alert("Official ECR import is available in the installed desktop app."); return;
  }
  let result;
  try{ result=await window.eclassAPI.importOfficialEcr(); }
  catch(err){ alert("Could not open the Official ECR importer: "+(err&&err.message?err.message:String(err))); return; }
  if(!result||result.cancelled) return;
  if(!result.ok){ alert("Could not read that Official ECR workbook: "+(result.error||"Unknown error")); return; }
  const proceed=await showOfficialEcrImportDialog(result.data,result.fileName,currentTermKey);
  if(!proceed) return;
  try{
    const stats=applyOfficialEcrImport(cls,result.data);
    saveState();
    activeTab=stats.termKey;
    render();
    const parts=[
      `${stats.learners} learner${stats.learners===1?"":"s"} read`,
      `${stats.importedScores} raw score${stats.importedScores===1?"":"s"} imported`
    ];
    if(stats.matched) parts.push(`${stats.matched} existing learner${stats.matched===1?"":"s"} matched`);
    if(stats.added) parts.push(`${stats.added} learner${stats.added===1?"":"s"} added to roster`);
    if(stats.invalid) parts.push(`${stats.invalid} invalid/out-of-HPS score${stats.invalid===1?"":"s"} skipped`);
    if(stats.gradeChecks) parts.push(stats.gradeMismatches?`${stats.gradeMismatches}/${stats.gradeChecks} cached Excel term grade${stats.gradeChecks===1?"":"s"} differed from the app's recalculation`:`${stats.gradeChecks} cached Excel term grade${stats.gradeChecks===1?"":"s"} verified against the app`);
    if(stats.warnings) parts.push(`${stats.warnings} workbook warning${stats.warnings===1?"":"s"}`);
    await showInfoDialog(`Official ECR Import Complete — ${TERM_LABELS[stats.termKey]}`,parts.join(" • "));
  }catch(err){ alert("Could not import the Official ECR data: "+(err&&err.message?err.message:String(err))); }
}



/* ===== v1.0.5: Official Class Record template export =====================
   The bundled XLSX is the actual required Class Record form. The renderer
   sends already-computed values to Electron; the main process fills a copy of
   that workbook without changing its formatting or print layout. */
function maxExistingScoreForComponent(cls,catKey,compId){
  let max=-Infinity;
  for(const termKey of ["term1","term2","term3"]){
    const term=cls.scores && cls.scores[termKey] || {};
    for(const sid of Object.keys(term)){
      const v=term[sid] && term[sid][catKey] && term[sid][catKey][compId];
      if(v===undefined || v===null || v==="") continue;
      const n=Number(v);if(Number.isFinite(n)) max=Math.max(max,n);
    }
  }
  return max===-Infinity?null:max;
}
function validateGradingConfiguration(cls,{official=false,termKey=null}={}){
  const errors=[];
  const cats=cls && cls.categories || {};
  const keys=["WW","PT","EXAM"];
  const termsToCheck=termKey ? [termKey] : ["term1","term2","term3"];
  const studentNameById=new Map((cls && Array.isArray(cls.students)?cls.students:[]).map(s=>[String(s.id),String(s.name||"Learner")]));
  let totalWeight=0;
  for(const key of keys){
    const cat=cats[key];
    if(!cat || !Array.isArray(cat.components)){errors.push(`${key}: missing grading category.`);continue;}
    const weight=Number(cat.weight);
    if(!Number.isFinite(weight) || weight<0 || weight>1) errors.push(`${key}: category weight must be from 0% to 100%.`);
    else totalWeight+=weight;
    if(official){
      const expected=key==="WW"?5:3;
      if(cat.components.length!==expected) errors.push(`${key}: official template requires exactly ${expected} components.`);
    }
    let customTotal=0;
    cat.components.forEach((c,i)=>{
      const h=Number(c.hps);
      if(!Number.isFinite(h) || h<0) errors.push(`${key}${i+1}: HPS must be 0 or greater.`);
      if(cat.mode==="custom"){
        const sw=Number(c.subWeight);
        if(!Number.isFinite(sw) || sw<0 || sw>100) errors.push(`${key}${i+1}: item weight must be from 0% to 100%.`);
        else if(Number.isFinite(h) && h>0) customTotal+=sw;
        else if(Number.isFinite(h) && h===0 && Math.abs(sw)>0.001) errors.push(`${key}${i+1}: an inactive item (HPS 0) must have 0% item weight.`);
      }
    });
    const activeCustom=cat.mode==="custom" && cat.components.some(c=>Number(c.hps)>0);
    if(activeCustom && Math.abs(customTotal-100)>0.001) errors.push(`${key}: active custom item weights must total exactly 100% (currently ${Math.round(customTotal*100)/100}%).`);
  }
  if(Math.abs(totalWeight-1)>0.0001) errors.push(`Category weights must total exactly 100% (currently ${Math.round(totalWeight*10000)/100}%).`);

  for(const checkTerm of termsToCheck){
    const term=cls.scores && cls.scores[checkTerm] || {};
    for(const [sid,scoreSet] of Object.entries(term)){
      const learner=studentNameById.get(String(sid)) || "Learner";
      for(const key of keys){
        const cat=cats[key];if(!cat)continue;
        const values=scoreSet && scoreSet[key] || {};
        for(let i=0;i<cat.components.length;i++){
          const c=cat.components[i];
          const raw=values[c.id];if(raw===undefined||raw===null||raw==="")continue;
          const n=Number(raw),h=Number(c.hps),label=String(c.name||`${key}${i+1}`);
          if(!Number.isFinite(n)||n<0) errors.push(`${checkTerm.toUpperCase()}: ${learner} has an invalid ${label} raw score.`);
          else if(!Number.isFinite(h)||h<0) errors.push(`${checkTerm.toUpperCase()}: ${label} has an invalid HPS.`);
          else if(h===0) errors.push(`${checkTerm.toUpperCase()}: ${learner} has ${label} score ${n}, but its HPS is 0.`);
          else if(n>h) errors.push(`${checkTerm.toUpperCase()}: ${learner}'s ${label} score ${n} exceeds its HPS ${h}.`);
          if(errors.length>=12) return errors;
        }
      }
    }
  }
  return errors;
}

function officialEcrPayload(cls, termKey){
  const validationErrors=validateGradingConfiguration(cls,{official:true,termKey});
  if(validationErrors.length) throw new Error("Please correct the grading setup/data before creating an official form:\n\n• "+validationErrors.slice(0,8).join("\n• "));
  const cats=cls.categories || {};
  const ww=cats.WW, pt=cats.PT, ex=cats.EXAM;
  if(!ww || !pt || !ex) throw new Error("The Class Record grading components are incomplete.");
  if(ww.components.length!==5 || pt.components.length!==3 || ex.components.length!==3){
    throw new Error("The official ECR template has fixed columns for 5 Written/Oral Works, 3 Performance Tasks, and 3 Examination components. Adjust the Class Record setup to 5 WW, 3 PT and 3 EX components before exporting.");
  }
  const males=cls.students.filter(s=>s.sex==="M"), females=cls.students.filter(s=>s.sex==="F");
  if(males.length>50 || females.length>50){
    throw new Error("The official ECR template provides 50 rows for male learners and 50 rows for female learners.");
  }

  const rawArray=(scoreMap,cat)=>cat.components.map(c=>{
    const v=scoreMap && scoreMap[c.id];
    return (v===undefined || v===null || v==="") ? "" : Number(v);
  });
  const anyRaw=(arr)=>arr.some(v=>v!=="");
  const round2=(v)=>Math.round(Number(v)*100)/100;

  const students=cls.students.map(st=>{
    const sm=(cls.scores[termKey] && cls.scores[termKey][st.id]) || {WW:{},PT:{},EXAM:{}};
    const result=studentTermResult(cls,termKey,st.id);
    const wwRaw=rawArray(sm.WW||{},ww), ptRaw=rawArray(sm.PT||{},pt), exRaw=rawArray(sm.EXAM||{},ex);
    const wwAny=anyRaw(wwRaw), ptAny=anyRaw(ptRaw), exAny=anyRaw(exRaw);
    const componentPs=ex.components.map((c,i)=>{
      if(exRaw[i]==="") return "";
      const h=Number(c.hps||0), sw=Number(c.subWeight||0);
      return h>0 ? round2(Number(exRaw[i])/h*sw) : "";
    });
    return {
      name:st.name||"", sex:st.sex||"M",
      WW:{scores:wwRaw,total:wwAny?round2(wwRaw.reduce((a,v)=>a+(v===""?0:Number(v)),0)):"",ps:result.parts.WW.ps??"",ws:result.parts.WW.ws??""},
      PT:{scores:ptRaw,total:ptAny?round2(ptRaw.reduce((a,v)=>a+(v===""?0:Number(v)),0)):"",ps:result.parts.PT.ps??"",ws:result.parts.PT.ws??""},
      EXAM:{scores:exRaw,componentPs,ps:exAny?(result.parts.EXAM.ps??""):"",ws:exAny?(result.parts.EXAM.ws??""):""},
      initial:result.initial??"", term:result.term??"", descriptor:result.band||""
    };
  });

  return {
    classId:cls.id||"",
    termKey,
    schoolLogoDataUri:schoolLogoDataUri(),
    meta:{...cls.meta},
    categories:{
      WW:{weight:Number(ww.weight||0),components:ww.components.map(c=>({name:c.name,hps:Number(c.hps||0),subWeight:Number(c.subWeight||0)}))},
      PT:{weight:Number(pt.weight||0),components:pt.components.map(c=>({name:c.name,hps:Number(c.hps||0),subWeight:Number(c.subWeight||0)}))},
      EXAM:{weight:Number(ex.weight||0),components:ex.components.map(c=>({name:c.name,hps:Number(c.hps||0),subWeight:Number(c.subWeight||0)}))}
    },
    students
  };
}

async function exportOfficialEcr(cls,termKey,mode="save"){
  try{
    const payload=officialEcrPayload(cls,termKey);

    // v1.0.16+: both preview and download go through the runtime template engine
    // so the Subject Teacher signatory and all current Setup values are present
    // in the actual official workbook, not only in the on-screen HTML view.
    if(window.eclassAPI && typeof window.eclassAPI.runtimeInvoke==="function"){
      const action=mode==="preview" ? "ecr:official-pdf-preview" : "ecr:official-save";
      const result=await window.eclassAPI.runtimeInvoke(action,payload);
      if(result && result.ok){
        if(mode==="save") await showInfoDialog("Official ECR Saved",`The official Class Record template was filled and saved successfully.\n\n${result.path||result.xlsxPath||""}`);
        return;
      }
      if(result && result.cancelled) return;
      if(result && result.previewUnavailable){
        await showInfoDialog("Official ECR Preview Unavailable",`${result.error||"Microsoft Excel could not render the official ECR preview."}\n\nThe filled official workbook is available here:\n${result.xlsxPath||result.path||""}`);
        return;
      }
      if(result && !result.unsupported){
        alert("Could not create the Official ECR: "+(result.error||"Unknown error"));
        return;
      }
    }

    // v1.0.20 stability gate: do not fall back to the retired bootstrap ECR
    // exporter. The bundled runtime extension is now the single authoritative
    // official-output engine, preventing regressions to the old Excel/formula path.
    alert("Official ECR output engine is unavailable. Please reinstall the v1.0.20 bootstrap or newer.");
    return;
  }catch(err){ alert("Could not create the Official ECR: "+(err&&err.message?err.message:String(err))); }
}

async function exportOfficialGs(cls,termKey,mode="preview"){
  if(!window.eclassAPI || typeof window.eclassAPI.runtimeInvoke!=="function"){
    alert("Official Grading Sheet output is available in the installed desktop app."); return;
  }
  try{
    const payload=officialEcrPayload(cls,termKey);
    const action=mode==="save" ? "gs:official-save" : "gs:official-pdf-preview";
    const result=await window.eclassAPI.runtimeInvoke(action,payload);
    if(result && result.ok){
      if(mode==="save") await showInfoDialog("Official Grading Sheet Saved",`The official Grading Sheet template was filled and saved successfully.\n\n${result.path||result.xlsxPath||""}`);
      return;
    }
    if(result && result.cancelled) return;
    if(result && result.previewUnavailable){
      await showInfoDialog("Official Grading Sheet Preview Unavailable",`${result.error||"Microsoft Excel could not render the official Grading Sheet preview."}\n\nThe filled official workbook is available here:\n${result.xlsxPath||result.path||""}`);
      return;
    }
    alert("Could not create the Official Grading Sheet: "+(result&&result.error?result.error:"Unknown error"));
  }catch(err){ alert("Could not create the Official Grading Sheet: "+(err&&err.message?err.message:String(err))); }
}

