function renderFinal(main, cls){
  if(!cls.students.length){
    main.innerHTML = `<div class="empty-state"><h2>No learners yet</h2><p>Add learners in the Roster tab first.</p></div>`;
    return;
  }
  const males = cls.students.filter(s=>s.sex==="M");
  const females = cls.students.filter(s=>s.sex==="F");
  function row(s){
    const t1 = studentTermResult(cls,"term1",s.id).term;
    const t2 = studentTermResult(cls,"term2",s.id).term;
    const t3 = studentTermResult(cls,"term3",s.id).term;
    const fin = studentFinalResult(cls, s.id);
    const bandHtml = fin.band ? `<span class="desc-band band-${fin.band}">${fin.band}</span>` : "—";
    return `<tr>
      <td class="name-cell">${esc(s.name)||"(unnamed)"}</td>
      <td class="computed">${t1===null||t1===undefined?"—":t1}</td>
      <td class="computed">${t2===null||t2===undefined?"—":t2}</td>
      <td class="computed">${t3===null||t3===undefined?"—":t3}</td>
      <td class="grade-final">${fin.final===null?"—":fin.final}</td>
      <td>${bandHtml}</td>
      <td class="hint">${fin.count} of 3 terms</td>
    </tr>`;
  }
  main.innerHTML = `
    <div class="card">
      <h2>Final Grades</h2>
      <div class="sub">Final Grade is the average of the term grades that have been entered so far (not assumed to be 3).</div>
      <div class="scroll-x">
      <table class="data">
        <thead><tr><th style="text-align:left;">Learner</th><th>Term 1</th><th>Term 2</th><th>Term 3</th><th>Final Grade</th><th>Descriptor</th><th>Progress</th></tr></thead>
        <tbody>
          <tr class="group-row"><td colspan="7">MALE</td></tr>
          ${males.map(row).join("") || `<tr><td colspan="7" class="hint">No male learners</td></tr>`}
          <tr class="group-row"><td colspan="7">FEMALE</td></tr>
          ${females.map(row).join("") || `<tr><td colspan="7" class="hint">No female learners</td></tr>`}
        </tbody>
      </table>
      </div>
    </div>`;
}

